#[derive(Default, serde::Serialize)]
struct Footprint {
    logical_bytes: u64,
    allocated_bytes: Option<u64>,
    files: u64,
}

fn footprint(path: &Path) -> std::io::Result<Footprint> {
    let mut result = Footprint {
        allocated_bytes: cfg!(unix).then_some(0),
        ..Default::default()
    };
    for entry in std::fs::read_dir(path)? {
